INSERT INTO "Settings" ("id", "key", "value", "description", "createdAt", "updatedAt") VALUES ('cmrsqxsir00005hklith8fizi', 'LANDING_PAGE_CMS', '{"seo":{"title":"Breakout Music Distribution","description":"Distribute your music worldwide to 150+ platforms.","keywords":"music, distribution, spotify, apple music, breakout"},"design":{"backgroundType":"image","backgroundColor":"#000000","backgroundImage":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/b05bc7b3-603b-4e8b-92a8-4e2c0d4a1a69.jpg","backgroundVideo":"https://youtu.be/D5U7g4B901s?si=xCMl5D-9O5rRfZ0s"},"hero":{"badge":"Breakout Music Record","title1":"Distribute Your Music","title2":"","subtitle":"Release your music to Spotify, Apple Music, TikTok, YouTube Music, Amazon Music, Deezer, Boomplay, Audiomack and 150+ streaming platforms worldwide.","ctaText":"Start Distributing","ctaLink":"/register","secondaryCtaText":"View Pricing","secondaryCtaLink":"#pricing","backgroundUrl":"https://releases.breakoutmusic.online/covers/1788938311471-6127691152321352313_121.jpg"},"about":{"title":"Tentang Breakout","description":"Breakout adalah layanan distribusi musik digital sekaligus label rekaman bagi musisi independen. Kami membantu mendistribusikan lagu Anda ke berbagai platform musik di seluruh dunia tanpa biaya tersembunyi.","imageUrl":"https://releases.breakoutmusic.online/covers/1788975661816-1000990984.png","isActive":true},"aboutLabel":{"title":"About Breakout Music Record","description":"We are more than just a label. We are a movement dedicated to pushing the boundaries of sound and giving independent artists a global stage.","vision":"To be the leading platform for independent artists globally, breaking barriers and redefining the music industry.","mission":"Providing top-tier distribution, marketing, and support to artists so they can focus on what they do best: creating music.","imageUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/610b2433-87b6-4a88-9d1e-e110121027c3.png","isActive":true},"featuredReleases":[],"featuredArtists":[],"musicVideos":[],"features":[{"id":"1","title":"Fast Distribution","description":"Your music is sent to over 150 platforms in a matter of hours. We ensure your releases are handled with the highest priority.","icon":"Music"},{"id":"2","title":"Advanced Analytics","description":"Track your streams, listeners, and revenue daily across all major platforms with our beautifully designed charts.","icon":"BarChart2"},{"id":"3","title":"Secure Royalties","description":"We collect your earnings worldwide and provide a seamless withdrawal system straight to your bank account.","icon":"ShieldCheck"}],"pricing":[],"faqSection":{"badge":"FAQ Breakout","title":"Pertanyaan yang sering ditanyakan","subtitle":"Jawaban singkat tentang akun Breakout, layanan Cover to Master, dan distribusi musik digital.","isActive":true},"faqGroups":[{"id":"1","title":"FAQ Umum","colorClass":"orange","order":1,"questions":[{"id":"1-1","question":"Apa itu Breakout?","answer":"Platform distribusi musik indie."},{"id":"1-2","question":"Apakah daftar di Breakout berbayar?","answer":"Gratis untuk pendaptaran tidak ada tagihan"},{"id":"1-3","question":"Bagaimana cara menggunakan layanan Breakout?","answer":"Buat akun, upload rilis, dan distribusikan."}]},{"id":"2","title":"FAQ CTM","colorClass":"green","order":2,"questions":[{"id":"2-1","question":"Apa itu CTM?","answer":"Cover to Master adalah layanan legalisasi cover lagu."},{"id":"2-2","question":"Kenapa cover saya kena copyright claim?","answer":"Karena belum ada lisensi resmi."}]},{"id":"3","title":"FAQ DMD","colorClass":"blue","order":3,"questions":[{"id":"3-1","question":"Apa itu DMD?","answer":"Digital Music Distribution."},{"id":"3-2","question":"Apakah karya original saya terlindungi?","answer":"Ya, kami menjaga hak cipta kreator."}]},{"id":"66befa8b-63f4-4cf5-a51d-3bc3640b0865","title":"FAQ Royalty","colorClass":"orange","order":4,"questions":[{"id":"fa8fcaff-974b-459f-8698-68378b7fdebf","question":"Berapa pembagian royalty yang diterima artist?","answer":"Pembagian royalti adalah 70% untuk artist dan 30% untuk label dari royalti bersih yang diterima."}]},{"id":"bc720f5b-1905-4053-a439-f555819b7720","title":"FAQ Rilis","colorClass":"green","order":5,"questions":[{"id":"9cf14530-e91e-42aa-ac10-401e9bd5d812","question":"Berapa lama proses rilis musik?","answer":"Proses distribusi dan rilis musik memerlukan waktu sekitar 7–14 hari kerja sejak semua data dan materi rilis dinyatakan lengkap serta lolos proses verifikasi."}]}],"testimonials":[{"id":"1","name":"Ikbal Sopan","role":"Artist","content":"Breakout sangat membantu karir musik saya!","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/a4eaa0d3-67a0-4168-8ec3-0f9a88f77eb0.jpg"},{"name":"FAREL PROJECT","role":"Artist","content":"Sebenarnya gw udah gila, Cuma males keliling aja","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/3ae887d1-08c0-4424-8416-556f07cb0e1c.jpg","id":"2b7298e9-7541-4b0a-86ff-30af985be905"},{"name":"Bang Novri","role":"Artist","content":"Bersama Break Out, saya mendapatkan dukungan terbaik untuk merilis karya saya!","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/001762ec-d278-4ccb-9930-85616aa0e7dc.jpg","id":"35c2e926-6a11-4f80-a5e7-96a093085631"},{"name":"Rellz Yete","role":"Artist","content":"Selayaknya harmoni dan melodi, walaupun beda dalam artian tapi sama sama punya tujuan untuk menciptakan nada yang indah","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/61a39652-66bf-466b-8655-b60818607020.jpg","id":"324f6cc3-6987-4727-82ad-a8e5050f19ef"},{"name":"YOGI SJ","role":"Artist","content":"1 setengah tahun, saya di hujat hujat gabisa remix saya diam, di cela di rendah rendahkan karna ga pernah viral saya juga diam, tetapi hari ini di breakout saya sampaikan SAYA AKAN LAWAN!!!","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/c7aa27d6-a582-465e-bd2e-a3e2e2878f31.jpg","id":"612db7ba-c65e-4c74-8aa7-008bc2fe8682"},{"name":"Sanfall","role":"Artist","content":"Breakout o nya josjis","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/fff1c7b6-9364-47b3-af3a-4a8097af508f.png","id":"e6cdb198-6b39-4e7a-87fe-965fb5b31181"},{"name":"Agus Sopan","role":"Artist","content":"Uwak cupid dida\"breakout new era jaya jaya jaya","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/e0d33fe9-8708-4932-93b4-42811d2fb2b9.jpg","id":"41a730ca-427b-4070-8255-ef3b59136a5b"},{"name":"King Boyy SOPAN","role":"Artist","content":"Pergi ke pasar membeli ikan, break out new era semakin di depan","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/a7bf9d7e-1f12-4aad-bfa7-8d727f047484.jpg","id":"04c09a94-379a-4cf0-857a-dc48c0238596"},{"name":"Jufri Oioi","role":"Artist","content":"Breakout,  Bertumbuh, Berproses, Dan Sukses Bersama","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/7ecae91a-6193-4ea7-9e1f-035ba8797447.jpg","id":"53cd7c5e-0b68-4a7a-9fcc-222e9dd30b4b"},{"name":"Rafi Fvnky","role":"Artist","content":"Jika Kamu Menemukan Seseorang Yang Membuatmu Bahagia Hari Ini, Jangan Lupakan Siapa Yang Peduli Padamu Kemarin","avatarUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/7f880b34-8950-45be-a7bc-2628b361b0c4.jpg","id":"4db83a30-881c-4fda-85f6-d9737cc686bc"}],"partners":[{"name":"","logoUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/c5ffb7ec-d4bd-4d2b-826c-a61aba7df183.png","id":"38b2a6b1-f9ef-4b40-b7b8-6a5f7f74eea0"},{"name":"","logoUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/9e715cbb-d1c5-47de-b233-604293d85955.png","id":"7041fcf6-9f3c-4cf0-9967-0fe5d9bf4462"},{"name":"","logoUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/914d7151-4ca2-4596-9176-5eb96097db3e.svg","id":"68a7abe8-435f-4710-a867-12c398834eb8"},{"name":"","logoUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/e3182e58-5cdc-4c33-8a27-f5c6ff4a9efe.png","id":"1c1b5192-0be9-4689-a3c5-8ad3b65ce1a5"},{"name":"","logoUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/17e17f22-e579-4cec-93f6-9f9d898da877.png","id":"606f276f-5aa4-4725-9e66-cf5db24988fe"},{"name":"","logoUrl":"https://techlixdaugqmypvcyvn.supabase.co/storage/v1/object/public/assets/cms/53dc924a-ddfe-40b9-a4a5-10a03a7befcb.png","id":"c1b199f0-352f-4c79-8ec7-c0172facaa45"}],"contact":{"email":"breakoutnewera.business@gmail.com","whatsapp":"+6281330923740","address":"Pati, Jawa Tengah, Indonesia","isActive":true},"footer":{"aboutText":"Breakout Music Distribution. Empowering independent artists worldwide.","copyright":"© 2026 Breakout Music Record. All rights reserved."},"socialMedia":{"instagram":"https://www.instagram.com/breakoutindo_?igsh=MTVzMTh6YXVtNmcxaw==","tiktok":"https://www.tiktok.com/@breakoutmusicrecord?_r=1&_t=ZS-98DuwRSQUAX","youtube":"https://youtube.com/@breakoutmusicrecord?si=fZj78MwmlwMXjP3U","spotify":"https://spotify.com/","whatsapp":"+6281330923740","email":"breakoutnewera.business@gmail.com"},"stats":{"totalArtists":200,"totalReleases":870,"totalStreams":7890067,"autoFromDb":false},"faq":[{"id":"1","question":"Berapa lama proses rilis?","answer":"Biasanya membutuhkan waktu 1-3 hari kerja untuk masuk ke Spotify dan Apple Music."}]}', 'Landing Page CMS Content', '2026-07-20T04:50:32.737Z', '2026-09-14T06:40:57.750Z');
