
-- Drop existing tables
DROP TABLE IF EXISTS "ActivityLog";
DROP TABLE IF EXISTS "Notification";
DROP TABLE IF EXISTS "WithdrawRequest";
DROP TABLE IF EXISTS "Contract";
DROP TABLE IF EXISTS "MessageRecipient";
DROP TABLE IF EXISTS "Message";
DROP TABLE IF EXISTS "RoyaltyPerSong";
DROP TABLE IF EXISTS "Royalty";
DROP TABLE IF EXISTS "Streaming";
DROP TABLE IF EXISTS "Track";
DROP TABLE IF EXISTS "Release";
DROP TABLE IF EXISTS "Artist";
DROP TABLE IF EXISTS "Admin";
DROP TABLE IF EXISTS "User";
DROP TABLE IF EXISTS "CatalogSong";
DROP TABLE IF EXISTS "Settings";

-- Create Tables for Cloudflare D1 (SQLite)
CREATE TABLE "User" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT,
  "email" TEXT UNIQUE NOT NULL,
  "password" TEXT NOT NULL,
  "emailVerified" TEXT,
  "image" TEXT,
  "whatsapp" TEXT,
  "youtubeUrl" TEXT,
  "ktpUrl" TEXT,
  "nik" TEXT,
  "address" TEXT,
  "role" TEXT DEFAULT 'USER',
  "status" TEXT DEFAULT 'PENDING',
  "rejectionReason" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now'))
);

CREATE TABLE "Admin" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT UNIQUE NOT NULL,
  "level" TEXT DEFAULT 'SUPERADMIN',
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE
);

CREATE TABLE "Artist" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT NOT NULL,
  "stageName" TEXT NOT NULL,
  "bio" TEXT,
  "avatarUrl" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE
);

CREATE TABLE "Release" (
  "id" TEXT PRIMARY KEY,
  "artistId" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "type" TEXT DEFAULT 'SINGLE',
  "genre" TEXT NOT NULL,
  "language" TEXT NOT NULL,
  "primaryArtist" TEXT NOT NULL,
  "featuredArtist" TEXT,
  "releaseDate" TEXT NOT NULL,
  "coverArtworkUrl" TEXT NOT NULL,
  "status" TEXT DEFAULT 'PENDING',
  "isImported" INTEGER DEFAULT 0,
  "upc" TEXT,
  "distributor" TEXT,
  "spotifyUrl" TEXT,
  "appleMusicUrl" TEXT,
  "youtubeMusicUrl" TEXT,
  "tiktokUrl" TEXT,
  "telegramMessageId" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("artistId") REFERENCES "Artist"("id") ON DELETE CASCADE
);

CREATE TABLE "Track" (
  "id" TEXT PRIMARY KEY,
  "releaseId" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "audioUrl" TEXT NOT NULL,
  "isrc" TEXT,
  "upc" TEXT,
  "composer" TEXT,
  "producer" TEXT,
  "lyrics" TEXT,
  "tiktokClipStart" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE
);

CREATE TABLE "Streaming" (
  "id" TEXT PRIMARY KEY,
  "trackId" TEXT NOT NULL,
  "platform" TEXT NOT NULL,
  "country" TEXT,
  "playCount" INTEGER DEFAULT 0,
  "date" TEXT NOT NULL,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("trackId") REFERENCES "Track"("id") ON DELETE CASCADE
);

CREATE TABLE "Royalty" (
  "id" TEXT PRIMARY KEY,
  "artistId" TEXT NOT NULL,
  "songName" TEXT NOT NULL,
  "month" INTEGER NOT NULL,
  "year" INTEGER NOT NULL,
  "spotifyStreams" INTEGER DEFAULT 0,
  "appleMusicStreams" INTEGER DEFAULT 0,
  "youtubeStreams" INTEGER DEFAULT 0,
  "tiktokStreams" INTEGER DEFAULT 0,
  "amazonStreams" INTEGER DEFAULT 0,
  "otherStreams" INTEGER DEFAULT 0,
  "platformData" TEXT,
  "totalRevenue" REAL DEFAULT 0,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("artistId") REFERENCES "Artist"("id") ON DELETE CASCADE
);

CREATE TABLE "RoyaltyPerSong" (
  "id" TEXT PRIMARY KEY,
  "artistId" TEXT NOT NULL,
  "trackId" TEXT,
  "songTitle" TEXT NOT NULL,
  "isrc" TEXT,
  "period" TEXT NOT NULL,
  "streams" INTEGER DEFAULT 0,
  "revenue" REAL DEFAULT 0,
  "notes" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("artistId") REFERENCES "Artist"("id") ON DELETE CASCADE,
  FOREIGN KEY ("trackId") REFERENCES "Track"("id") ON DELETE SET NULL
);

CREATE TABLE "WithdrawRequest" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT NOT NULL,
  "bankName" TEXT NOT NULL,
  "accountNumber" TEXT NOT NULL,
  "accountName" TEXT NOT NULL,
  "amount" REAL NOT NULL,
  "status" TEXT DEFAULT 'PENDING',
  "notes" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE
);

CREATE TABLE "Contract" (
  "id" TEXT PRIMARY KEY,
  "userId" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "fileUrl" TEXT NOT NULL,
  "status" TEXT DEFAULT 'PENDING',
  "signedAt" TEXT,
  "notes" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now')),
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE
);

CREATE TABLE "CatalogSong" (
  "id" TEXT PRIMARY KEY,
  "title" TEXT NOT NULL,
  "artist" TEXT NOT NULL,
  "vokal" TEXT,
  "publisher" TEXT,
  "genre" TEXT,
  "driveLink" TEXT,
  "coverUrl" TEXT,
  "audioUrl" TEXT,
  "isDownloadable" INTEGER DEFAULT 1,
  "isActive" INTEGER DEFAULT 1,
  "isrc" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now'))
);

CREATE TABLE "Settings" (
  "id" TEXT PRIMARY KEY,
  "key" TEXT UNIQUE NOT NULL,
  "value" TEXT NOT NULL,
  "description" TEXT,
  "createdAt" TEXT DEFAULT (DATETIME('now')),
  "updatedAt" TEXT DEFAULT (DATETIME('now'))
);


